SELECT COUNT(*)
FROM OP_WISHLIST
WHERE
	USER_ID = #{userId}
	AND ITEM_ID = #{itemId}

mapper.insert:
/* saleson.shop.wishlist.WishlistMapper.insertWishlist */
INSERT INTO OP_WISHLIST (WISHLIST_ID, WISHLIST_GROUP_ID, ITEM_ID, ITEM_OPTION, ITEM_OPTION_GROUP_NAME, ITEM_OPTION_NAME,USER_ID, CREATED_DATE)
VALUES (#{wishlistId}, #{wishlistGroupId}, #{itemId}, #{itemOption}, #{itemOptionGroupName}, #{itemOptionName}, #{userId}, )

mapper.update:
/* saleson.shop.wishlist.WishlistMapper.updateWishlist */
UPDATE OP_WISHLIST SET
	WISHLIST_GROUP_ID = #{wishlistGroupId},
	ITEM_ID = #{itemId},
	ITEM_OPTION = #{itemOption},
	ITEM_OPTION_GROUP_NAME = #{itemOptionGroupName},
	ITEM_OPTION_NAME = #{itemOptionName}
WHERE WISHLIST_ID = #{wishlistId}

sql.where:
